(function(root){
const mean=a=>a.reduce((s,x)=>s+x,0)/Math.max(1,a.length);
function predict(rows,date){const dow=new Date(date+'T12:00:00Z').getUTCDay();const recent=rows.slice(-28),same=recent.filter(r=>new Date(r.date+'T12:00:00Z').getUTCDay()===dow);const trend=Math.max(.8,Math.min(1.2,mean(rows.slice(-7).map(r=>r.sold))/Math.max(1,mean(rows.slice(-21,-7).map(r=>r.sold)))));return Math.max(0,Math.round((.8*mean((same.length?same:recent).map(r=>r.sold))+.2*mean(recent.map(r=>r.sold)))*trend));}
function evaluate(rows){let error=0,base=0,total=0;for(let i=28;i<rows.length;i++){const train=rows.slice(0,i),r=rows[i];error+=Math.abs(predict(train,r.date)-r.sold);base+=Math.abs(mean(train.slice(-7).map(x=>x.sold))-r.sold);total+=r.sold;}return {wape:total?error/total*100:null,baseline:total?base/total*100:null,n:Math.max(0,rows.length-28)};}
function demo(){const items=[['Самса с говядиной',540,290,96],['Круассан',750,360,58],['Баурсаки · порция',650,250,72],['Сэндвич с курицей',1200,650,38]];let rows=[];items.forEach(([product,price,cost,q],j)=>{for(let i=0;i<56;i++){const d=new Date(Date.UTC(2026,7,24+i)),day=d.getUTCDay(),sold=Math.round(q*(day===0?1.25:day===6?1.45:day===1?.77:1)+(Math.sin(i*2.31+j)*q*.09)+i*.13);rows.push({date:d.toISOString().slice(0,10),product,sold,prepared:sold+Math.round(q*(.12+.1*Math.abs(Math.cos(i+j)))),price,cost});}});return rows;}
if(typeof module!=='undefined')module.exports={predict,evaluate,demo};root.QorModel={predict,evaluate,demo};})(typeof window==='undefined'?globalThis:window);
